copy.text:
git clone https://github.com/keyona-rerev/knowledge-loom-prismm.git {{repo_name}}
cd {{repo_name}}
git remote set-url origin https://github.com/{{github_username}}/{{repo_name}}.git
git rm -f .env
git rm -rf setup-wizard

npx supabase login
npx supabase link --project-ref {{supabase_project_ref}}
npx supabase db push

update public.automation_config set value = '{{supabase_url}}' where key = 'project_url';
update public.automation_config set value = 'PASTE_YOUR_ANON_KEY' where key = 'project_anon_key';
insert into public.automation_config (key, value) values ('app_url', '{{app_url}}'), ('alert_from_email', '{{from_email}}')
on conflict (key) do update set value = excluded.value;

business_name={{business_name}}
color_background={{color_background}}
color_accent={{color_accent}}
color_highlight={{color_highlight}}
color_sparing_accent={{color_sparing_accent}}
logo_url={{logo_url}}
font_names={{font_names}}
posting_timezone={{posting_timezone}}
posting_time={{posting_time}}
posting_cadence={{posting_cadence}}
